149	+-- New functions are not executable without a login. Grant anon explicitly where a client or policy needs it.
150	+ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE ALL ON FUNCTIONS FROM anon;
151	+-- PUBLIC gets EXECUTE on new functions by default, and anon inherits it. Only a global default, not a per-schema one, can remove it.
152	+ALTER DEFAULT PRIVILEGES FOR ROLE postgres REVOKE EXECUTE ON FUNCTIONS FROM public;
153	+
154	+-- Every role that calls our functions holds its own grant, so PUBLIC's grant only matters for anon.
155	+-- Removing it makes existing functions match the ones created under the defaults above.
156	+DO $$
157	+DECLARE
158	+    fn regprocedure;
159	+BEGIN
160	+    FOR fn IN
161	+        SELECT p.oid::regprocedure FROM pg_catalog.pg_proc AS p
162	+        WHERE p.pronamespace = 'public'::regnamespace
163	+        AND p.proowner = 'postgres'::regrole
164	+        AND NOT EXISTS (
165	+            SELECT 1 FROM pg_catalog.pg_depend AS d
166	+            WHERE d.classid = 'pg_catalog.pg_proc'::regclass AND d.objid = p.oid AND d.deptype = 'e'
167	+        )
168	+    LOOP
169	+        EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC', fn);
170	+    END LOOP;
171	+END;
172	+$$;
173	+
174	+-- Only triggers call these. Postgres checks EXECUTE on a trigger function when the trigger is created, not when it fires.
175	+REVOKE ALL ON FUNCTION public.after_delete_space() FROM anon, authenticated;
